-- Snapshot of all public functions on nilo-bottle (exported 2026-11-28). Whitespace is flattened by the export.
-- Tables and policies are not in this file yet: see supabase/README.md.

CREATE OR REPLACE FUNCTION public.add_chain_line(p_chain uuid, p_body text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare t text := left(trim(coalesce(p_body,'')), 160); n integer; v_cc text; begin if auth.uid() is null then return false; end if; if char_length(t) < 3 or t ~* '(https?://|www\.|@|t\.me|wa\.me|\.com|\.net|\.org)' or t ~ '[0-9٠-٩]{6,}' then raise exception 'bad_text'; end if; select lines into n from public.chains where id = p_chain and holder = auth.uid() and status = 'held' for update; if n is null then return false; end if; select p.cc into v_cc from public.profiles p where p.id = auth.uid(); insert into public.chain_lines(chain, author, country, body, pos) values (p_chain, auth.uid(), v_cc, t, n + 1); update public.chains set lines = n + 1, holder = null, held_at = null, status = case when n + 1 >= 6 then 'done' else 'open' end where id = p_chain; return true; end $function$;

 CREATE OR REPLACE FUNCTION public.bottle_journey(p_id text) RETURNS TABLE(from_cc text, to_cc text, sent_at timestamp with time zone, caught boolean) LANGUAGE sql SECURITY DEFINER SET search_path TO 'public' AS $function$ select pa.cc, pc.cc, b.created_at, (b.catcher is not null) from public.bottles b left join public.profiles pa on pa.id = b.author left join public.profiles pc on pc.id = b.catcher where b.id::text = p_id and (b.author = auth.uid() or b.catcher = auth.uid()); $function$;

 CREATE OR REPLACE FUNCTION public.card_reveal(p_pick integer) RETURNS json LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare w public.wallet; today date := (now() at time zone 'utc')::date; used int; r int; reward int; begin if auth.uid() is null then raise exception 'auth'; end if; if p_pick is null or p_pick < 0 or p_pick > 8 then raise exception 'bad_pick'; end if; insert into public.wallet(uid) values (auth.uid()) on conflict do nothing; select * into w from public.wallet where uid = auth.uid() for update; used := case when w.cards_day = today then w.cards_used else 0 end; if used >= 1 then raise exception 'ad_required'; end if; r := floor(random() * 100); reward := case when r < 50 then 5 when r < 78 then 10 when r < 92 then 15 when r < 98 then 25 else 50 end; update public.wallet set gems = gems + reward, xp = xp + 2, cards_day = today, cards_used = used + 1 where uid = auth.uid(); return json_build_object('reward', reward, 'gems', w.gems + reward); end $function$;

 CREATE OR REPLACE FUNCTION public.card_state() RETURNS json LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare w public.wallet; today date := (now() at time zone 'utc')::date; begin if auth.uid() is null then raise exception 'auth'; end if; insert into public.wallet(uid) values (auth.uid()) on conflict do nothing; select * into w from public.wallet where uid = auth.uid(); return json_build_object('used', case when w.cards_day = today then w.cards_used else 0 end, 'free', 1, 'frame', w.frame, 'skin', w.skin, 'xp', w.xp, 'gems', w.gems); end $function$;

 CREATE OR REPLACE FUNCTION public.catch_bottle() RETURNS bottles LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare b public.bottles; begin if not exists (select 1 from public.profiles where id = auth.uid() and age_ok) then raise exception 'age confirmation required'; end if; select * into b from public.bottles where status = 'floating' and author <> auth.uid() and not exists (select 1 from public.blocks k where (k.blocker = auth.uid() and k.blocked = bottles.author) or (k.blocker = bottles.author and k.blocked = auth.uid())) order by random() limit 1 for update skip locked; if b.id is null then return null; end if; update public.bottles set status = 'caught', catcher = auth.uid() where id = b.id returning * into b; return b; end $function$;

 CREATE OR REPLACE FUNCTION public.catch_chain() RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare c uuid; begin if auth.uid() is null then return null; end if; if not exists (select 1 from public.profiles where id = auth.uid() and age_ok) then return null; end if; select id into c from public.chains ch where ch.status = 'held' and ch.holder = auth.uid() and ch.held_at > now() - interval '1 day' limit 1; if c is not null then return c; end if; select ch.id into c from public.chains ch where (ch.status = 'open' or (ch.status = 'held' and ch.held_at < now() - interval '1 day')) and not exists (select 1 from public.chain_lines l where l.chain = ch.id and l.author = auth.uid()) and not exists (select 1 from public.chain_lines l join public.blocks k on (k.blocker = auth.uid() and k.blocked = l.author) or (k.blocked = auth.uid() and k.blocker = l.author) where l.chain = ch.id) order by ch.created_at limit 1 for update skip locked; if c is null then return null; end if; update public.chains set status = 'held', holder = auth.uid(), held_at = now() where id = c; return c; end $function$;

 CREATE OR REPLACE FUNCTION public.catch_specific(p_id uuid) RETURNS bottles LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare b public.bottles; begin if not exists (select 1 from public.profiles where id = auth.uid() and age_ok) then raise exception 'age confirmation required'; end if; select * into b from public.bottles where id = p_id and status = 'floating' and author <> auth.uid() and not exists (select 1 from public.blocks k where (k.blocker = auth.uid() and k.blocked = bottles.author) or (k.blocker = bottles.author and k.blocked = auth.uid())) for update skip locked; if b.id is null then return null; end if; update public.bottles set status = 'caught', catcher = auth.uid() where id = b.id returning * into b; return b; end $function$;

 CREATE OR REPLACE FUNCTION public.chain_view(p_chain uuid) RETURNS TABLE(pos integer, body text, country text, mine boolean, id uuid) LANGUAGE sql SECURITY DEFINER SET search_path TO 'public' AS $function$ select l.pos, l.body, l.country, (l.author = auth.uid()), l.id from public.chain_lines l join public.chains ch on ch.id = l.chain where l.chain = p_chain and l.reports < 2 and (ch.holder = auth.uid() or public.nilo_in_chain(p_chain)) order by l.pos; $function$;

 CREATE OR REPLACE FUNCTION public.challenge_board(p_week integer) RETURNS TABLE(cc text, n integer) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ begin if auth.uid() is null then raise exception 'auth'; end if; if (select count(*) from public.challenge_done where week=p_week) < 10 then return; end if; return query select p.cc, count(*)::int from public.challenge_done d join public.profiles p on p.id=d.uid where d.week=p_week and p.cc is not null group by p.cc order by 2 desc limit 15; end $function$;

 CREATE OR REPLACE FUNCTION public.challenge_tick(p_week integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ begin if auth.uid() is null then raise exception 'auth'; end if; if p_week < 0 or p_week > 100000 then raise exception 'bad'; end if; insert into public.challenge_done(uid,week) values (auth.uid(),p_week) on conflict do nothing; end $function$;

 CREATE OR REPLACE FUNCTION public.circle_limit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ begin if (select count(*) from public.circle_posts where author = new.author and created_at > now() - interval '24 hours') >= 10 then raise exception 'daily circle limit'; end if; return new; end $function$;

 CREATE OR REPLACE FUNCTION public.close_bottle(p_id uuid) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path TO 'public' AS $function$ update public.bottles set status = 'closed' where id = p_id and (author = auth.uid() or catcher = auth.uid()); $function$;

 CREATE OR REPLACE FUNCTION public.create_event_room(p_name text, p_at timestamp with time zone) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare g uuid; c text; begin if auth.uid() is null then return ''; end if; if not exists (select 1 from public.profiles where id = auth.uid() and age_ok) then return ''; end if; if char_length(trim(p_name)) < 2 or p_name ~* '(https?://|www\.|@|t\.me|wa\.me|\.com|\.net|\.org)' or p_name ~ '[0-9٠-٩]{6,}' then raise exception 'bad_text'; end if; if (select count(*) from public.chat_groups where owner = auth.uid()) >= 5 then raise exception 'too many groups'; end if; c := substr(md5(random()::text || clock_timestamp()::text), 1, 8); insert into public.chat_groups(name, code, owner, event_at) values (left(trim(p_name),40), c, auth.uid(), p_at) returning id into g; insert into public.chat_members(grp, uid) values (g, auth.uid()); return c; end $function$;

 CREATE OR REPLACE FUNCTION public.create_group(p_name text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare g uuid; c text; begin if auth.uid() is null then return ''; end if; if not exists (select 1 from public.profiles where id = auth.uid() and age_ok) then return ''; end if; if char_length(trim(p_name)) < 2 or p_name ~* '(https?://|www\.|@|t\.me|wa\.me|\.com|\.net|\.org)' or p_name ~ '[0-9٠-٩]{6,}' then raise exception 'bad_text'; end if; if (select count(*) from public.chat_groups where owner = auth.uid()) >= 5 then raise exception 'too many groups'; end if; c := substr(md5(random()::text || clock_timestamp()::text), 1, 8); insert into public.chat_groups(name, code, owner) values (left(trim(p_name),40), c, auth.uid()) returning id into g; insert into public.chat_members(grp, uid) values (g, auth.uid()); return c; end $function$;

 CREATE OR REPLACE FUNCTION public.da_force_day() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ begin new.day := (now() at time zone 'utc')::date; new.reports := 0; return new; end $function$;

 CREATE OR REPLACE FUNCTION public.delete_my_account() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'auth' AS $function$ declare u uuid := auth.uid(); begin if u is null then raise exception 'not signed in'; end if; update public.bottles set catcher = null, status = 'closed' where catcher = u; update public.letters set opened_by = null where opened_by = u; update public.profiles set invited_by = null where invited_by = u; delete from public.circle_reports where reporter = u; delete from public.daily_reports where reporter = u; delete from public.place_reports where reporter = u; delete from public.tip_reports where reporter = u; delete from auth.users where id = u; end $function$;

 CREATE OR REPLACE FUNCTION public.delete_my_bottle(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ begin if not exists (select 1 from public.bottles where id = p_id and author = auth.uid()) then raise exception 'not yours'; end if; delete from public.replies where bottle_id = p_id; delete from public.bottles where id = p_id and author = auth.uid(); end $function$;

 CREATE OR REPLACE FUNCTION public.dm_unread() RETURNS integer LANGUAGE sql SECURITY DEFINER SET search_path TO 'public' AS $function$ select count(*)::int from public.dms where recipient = auth.uid() and created_at > now() - interval '3 days' and reports < 2; $function$;

 CREATE OR REPLACE FUNCTION public.expired_objects() RETURNS SETOF text LANGUAGE sql SECURITY DEFINER SET search_path TO 'public', 'storage' AS $function$ select name from storage.objects where bucket_id = 'stories' and created_at < now() - interval '25 hours' limit 20 $function$;

 CREATE OR REPLACE FUNCTION public.find_user(p_name text) RETURNS json LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare w public.wallet; nm text := btrim(coalesce(p_name,'')); res json; begin if auth.uid() is null then raise exception 'auth'; end if; if length(nm) < 2 then raise exception 'short'; end if; insert into public.wallet(uid) values (auth.uid()) on conflict do nothing; select * into w from public.wallet where uid = auth.uid() for update; if coalesce((w.items ->> 'eye')::int, 0) < 1 then raise exception 'no_eye'; end if; update public.wallet set items = jsonb_set(items, '{eye}', to_jsonb((items ->> 'eye')::int - 1)) where uid = auth.uid(); select coalesce(json_agg(x), '[]'::json) into res from ( select p.id as uid, p.nick, p.avatar, p.avatar_path, p.cc from public.profiles p where lower(p.nick) = lower(nm) and p.age_ok and p.id <> auth.uid() and not exists (select 1 from public.blocks b where (b.blocker = auth.uid() and b.blocked = p.id) or (b.blocker = p.id and b.blocked = auth.uid())) limit 5) x; return res; end $function$;

 CREATE OR REPLACE FUNCTION public.floating_count() RETURNS integer LANGUAGE sql SECURITY DEFINER SET search_path TO 'public' AS $function$ select count(*)::int from public.bottles b where b.status='floating' and b.author <> auth.uid() and not exists (select 1 from public.blocks k where (k.blocker=auth.uid() and k.blocked=b.author) or (k.blocker=b.author and k.blocked=auth.uid())) $function$;

 CREATE OR REPLACE FUNCTION public.floating_peek() RETURNS json LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare res json; begin if auth.uid() is null then raise exception 'auth'; end if; select coalesce(json_agg(x), '[]'::json) into res from ( select b.id, p.nick, p.cc, b.kind from public.bottles b join public.profiles p on p.id = b.author where b.status = 'floating' and b.author <> auth.uid() and p.cc is not null and p.age_ok and not exists (select 1 from public.blocks k where (k.blocker = auth.uid() and k.blocked = b.author) or (k.blocker = b.author and k.blocked = auth.uid())) and (select count(*) from public.profile_reports r where r.target = b.author) < 2 order by random() limit 6) x; return res; end $function$;

 CREATE OR REPLACE FUNCTION public.flying_by_country() RETURNS TABLE(cc text, n integer) LANGUAGE sql SECURITY DEFINER SET search_path TO 'public' AS $function$ select p.cc, count(*)::int from public.bottles b join public.profiles p on p.id = b.author where b.catcher is null and p.cc is not null group by p.cc having count(*) >= 3 order by 2 desc limit 40; $function$;

 CREATE OR REPLACE FUNCTION public.founder_announce(p_title text, p_body text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ begin if not public.nilo_is_founder() then raise exception 'no'; end if; update public.announcements set active = false where active; insert into public.announcements(title, body) values (left(trim(p_title),80), left(coalesce(p_body,''),400)); end $function$;

 CREATE OR REPLACE FUNCTION public.founder_clear_announce() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ begin if not public.nilo_is_founder() then raise exception 'no'; end if; update public.announcements set active = false where active; end $function$;

 CREATE OR REPLACE FUNCTION public.founder_remove(p_kind text, p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ begin if not public.nilo_is_founder() then raise exception 'no'; end if; if p_kind = 'story' then delete from public.stories where id = p_id; elsif p_kind = 'circle' then delete from public.circle_posts where id = p_id; elsif p_kind = 'daily' then delete from public.daily_answers where id = p_id; elsif p_kind = 'chain' then delete from public.chain_lines where id = p_id; end if; end $function$;

 CREATE OR REPLACE FUNCTION public.founder_reports() RETURNS TABLE(kind text, id uuid, body text, reports integer) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ begin if not public.nilo_is_founder() then raise exception 'no'; end if; return query select 'story'::text, s.id, s.body, s.reports from public.stories s where s.reports > 0 union all select 'circle', c.id, c.body, c.reports from public.circle_posts c where c.reports > 0 union all select 'daily', d.id, d.body, d.reports from public.daily_answers d where d.reports > 0 union all select 'chain', l.id, l.body, l.reports from public.chain_lines l where l.reports > 0 order by 4 desc limit 60; end $function$;

 CREATE OR REPLACE FUNCTION public.founder_stats() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare r jsonb; begin if not public.nilo_is_founder() then raise exception 'no'; end if; select jsonb_build_object( 'members', (select count(*) from public.profiles where age_ok and cc is not null), 'papyri_total', (select count(*) from public.bottles), 'papyri_24h', (select count(*) from public.bottles where created_at > now() - interval '24 hours'), 'stories_24h', (select count(*) from public.stories where created_at > now() - interval '24 hours'), 'answers_24h', (select count(*) from public.daily_answers where created_at > now() - interval '24 hours'), 'friends', (select count(*) from public.friendships where status = 'accepted'), 'groups', (select count(*) from public.chat_groups), 'chains', (select count(*) from public.chains), 'reported_items', (select (select count(*) from public.stories where reports > 0) + (select count(*) from public.circle_posts where reports > 0) + (select count(*) from public.daily_answers where reports > 0) + (select count(*) from public.chain_lines where reports > 0)), 'countries', (select coalesce(jsonb_object_agg(cc, n), '{}'::jsonb) from (select cc, count(*) n from public.profiles where age_ok and cc is not null group by cc order by n desc limit 10) t) ) into r; return r; end $function$;

 CREATE OR REPLACE FUNCTION public.friend_ids() RETURNS uuid[] LANGUAGE sql SECURITY DEFINER SET search_path TO 'public' AS $function$ select coalesce(array_agg(case when f.requester = auth.uid() then f.target else f.requester end), '{}') from public.friendships f where f.status = 'accepted' and (f.requester = auth.uid() or f.target = auth.uid()) and not exists (select 1 from public.blocks k where (k.blocker = auth.uid() and k.blocked in (f.requester, f.target)) or (k.blocked = auth.uid() and k.blocker in (f.requester, f.target))); $function$;

 CREATE OR REPLACE FUNCTION public.get_profile(p_uid uuid) RETURNS TABLE(nick text, bio text, avatar text, avatar_path text, gender text) LANGUAGE sql SECURITY DEFINER SET search_path TO 'public' AS $function$ select p.nick, p.bio, p.avatar, case when (select count(*) from public.profile_reports r where r.target = p.id) >= 2 then '' else p.avatar_path end, p.gender from public.profiles p where p.id = p_uid and not exists (select 1 from public.blocks b where b.blocker = auth.uid() and b.blocked = p.id); $function$;

 CREATE OR REPLACE FUNCTION public.get_public_photos(p_uid uuid) RETURNS TABLE(path text) LANGUAGE sql SECURITY DEFINER SET search_path TO 'public' AS $function$ select p.path from public.profile_photos p where p.uid = p_uid and p.is_public and auth.uid() is not null and not exists (select 1 from public.blocks k where (k.blocker = p_uid and k.blocked = auth.uid()) or (k.blocker = auth.uid() and k.blocked = p_uid)) order by p.created_at desc limit 6 $function$;

 CREATE OR REPLACE FUNCTION public.invite_count() RETURNS integer LANGUAGE sql SECURITY DEFINER SET search_path TO 'public' AS $function$ select count(*)::int from public.profiles where invited_by = auth.uid() $function$;

 CREATE OR REPLACE FUNCTION public.join_group(p_code text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare g uuid; begin if auth.uid() is null then return 'auth'; end if; if not exists (select 1 from public.profiles where id = auth.uid() and age_ok) then return 'age'; end if; select id into g from public.chat_groups where code = lower(trim(p_code)); if g is null then return 'nocode'; end if; if exists (select 1 from public.chat_members where grp = g and uid = auth.uid()) then return 'ok'; end if; if (select count(*) from public.chat_members where grp = g) >= 12 then return 'full'; end if; insert into public.chat_members(grp, uid) values (g, auth.uid()); return 'ok'; end $function$;

 CREATE OR REPLACE FUNCTION public.journey_claim() RETURNS json LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare w public.wallet; n int; st public.journey_stations; today date := (now() at time zone 'utc')::date; ns int; bonus int; begin if auth.uid() is null then raise exception 'auth'; end if; insert into public.wallet(uid) values (auth.uid()) on conflict do nothing; select * into w from public.wallet where uid = auth.uid() for update; if w.last_claim = today then raise exception 'already'; end if; select count(*) into n from public.journey_stations; select * into st from public.journey_stations where idx = w.journey_pos % n; ns := case when w.last_claim = today - 1 then w.streak + 1 else 1 end; bonus := case when ns % 7 = 0 then 20 else 0 end; update public.wallet set gems = gems + st.gems + bonus, xp = xp + 10, journey_pos = journey_pos + 1, streak = ns, last_claim = today where uid = auth.uid(); return (public.journey_state()::jsonb || jsonb_build_object('reward', st.gems + bonus, 'bonus', bonus))::json; end $function$;

 CREATE OR REPLACE FUNCTION public.journey_state() RETURNS json LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare w public.wallet; n int; st public.journey_stations; today date := (now() at time zone 'utc')::date; cl boolean; sidx int; begin if auth.uid() is null then raise exception 'auth'; end if; insert into public.wallet(uid) values (auth.uid()) on conflict do nothing; select * into w from public.wallet where uid = auth.uid(); select count(*) into n from public.journey_stations; cl := (w.last_claim = today); sidx := case when cl then (w.journey_pos - 1 + n) % n else w.journey_pos % n end; select * into st from public.journey_stations where idx = sidx; return json_build_object('gems', w.gems, 'xp', w.xp, 'streak', case when w.last_claim is null or w.last_claim < today - 1 then 0 else w.streak end, 'pos', w.journey_pos, 'claimed', coalesce(cl,false), 'total', n, 'station', row_to_json(st)); end $function$;

 CREATE OR REPLACE FUNCTION public.leave_group(p_grp uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ begin delete from public.chat_members where grp = p_grp and uid = auth.uid(); if not exists (select 1 from public.chat_members where grp = p_grp) then delete from public.chat_groups where id = p_grp; end if; end $function$;

 CREATE OR REPLACE FUNCTION public.letters_limit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ begin if (select count(*) from public.letters where author = new.author and created_at > now() - interval '24 hours') >= 5 then raise exception 'daily letter limit'; end if; return new; end $function$;

 CREATE OR REPLACE FUNCTION public.letters_waiting(c text, ct text) RETURNS integer LANGUAGE sql SECURITY DEFINER SET search_path TO 'public' AS $function$ select count(*)::int from public.letters where cc = upper(c) and lower(city) = lower(ct) and opened_by is null and author <> auth.uid() $function$;

 CREATE OR REPLACE FUNCTION public.my_chains() RETURNS TABLE(id uuid, status text, lines integer, first_line text) LANGUAGE sql SECURITY DEFINER SET search_path TO 'public' AS $function$ select ch.id, ch.status, ch.lines, (select body from public.chain_lines l where l.chain = ch.id and l.pos = 1) from public.chains ch where public.nilo_in_chain(ch.id) order by ch.created_at desc limit 50; $function$;

 CREATE OR REPLACE FUNCTION public.my_friends() RETURNS TABLE(uid uuid, nick text, avatar text, cc text, status text, incoming boolean) LANGUAGE sql SECURITY DEFINER SET search_path TO 'public' AS $function$ select p.id, p.nick, p.avatar, p.cc, f.status, (f.target = auth.uid()) from public.friendships f join public.profiles p on p.id = case when f.requester = auth.uid() then f.target else f.requester end where (f.requester = auth.uid() or f.target = auth.uid()) and not exists (select 1 from public.blocks k where (k.blocker = auth.uid() and k.blocked = p.id) or (k.blocker = p.id and k.blocked = auth.uid())) order by f.created_at desc limit 200; $function$;

 CREATE OR REPLACE FUNCTION public.my_groups() RETURNS TABLE(id uuid, name text, code text, members integer, event_at timestamp with time zone) LANGUAGE sql SECURITY DEFINER SET search_path TO 'public' AS $function$ select g.id, g.name, g.code, (select count(*)::int from public.chat_members m2 where m2.grp = g.id), g.event_at from public.chat_groups g join public.chat_members m on m.grp = g.id and m.uid = auth.uid() order by g.created_at desc; $function$;

 CREATE OR REPLACE FUNCTION public.my_invite_code() RETURNS text LANGUAGE sql SECURITY DEFINER SET search_path TO 'public' AS $function$ select invite_code from public.profiles where id = auth.uid() $function$;

 CREATE OR REPLACE FUNCTION public.nilo_country_counts() RETURNS TABLE(cc text, travelers bigint, letters bigint) LANGUAGE sql SECURITY DEFINER SET search_path TO 'public' AS $function$ select x.c, sum(x.t)::bigint, sum(x.l)::bigint from ( select p.cc as c, 1 as t, 0 as l from public.profiles p where p.cc is not null union all select l.cc as c, 0 as t, 1 as l from public.letters l where l.cc is not null and l.opened_by is null ) x group by x.c order by 2 desc; $function$;

 CREATE OR REPLACE FUNCTION public.nilo_in_chain(c uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $function$ select exists (select 1 from public.chain_lines where chain = c and author = auth.uid()); $function$;

 CREATE OR REPLACE FUNCTION public.nilo_in_group(g uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $function$ select exists (select 1 from public.chat_members where grp = g and uid = auth.uid()); $function$;

 CREATE OR REPLACE FUNCTION public.nilo_is_founder() RETURNS boolean LANGUAGE sql STABLE AS $function$ select auth.uid() = '6b8f6fbd-828e-40ef-832e-58ce6ec8ca78'::uuid; $function$;

 CREATE OR REPLACE FUNCTION public.nilo_norm(t text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path TO 'public' AS $function$ select regexp_replace(lower(btrim(coalesce(t,''))), '^(the |a |an |ال)', '') $function$;

 CREATE OR REPLACE FUNCTION public.nilo_rate_limit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare n int; begin if tg_table_name = 'bottles' then select count(*) into n from public.bottles where author = new.author and created_at > now() - interval '1 day'; if n >= 30 then raise exception 'rate_limit'; end if; elsif tg_table_name = 'replies' then select count(*) into n from public.replies where author = new.author and created_at > now() - interval '1 day'; if n >= 300 then raise exception 'rate_limit'; end if; end if; return new; end $function$;

 CREATE OR REPLACE FUNCTION public.nilo_rl_friends() RETURNS trigger LANGUAGE plpgsql AS $function$ begin if (select count(*) from public.friendships where requester = new.requester and created_at > now() - interval '24 hours') >= 20 then raise exception 'rate limit: too many friend requests today'; end if; return new; end $function$;

 CREATE OR REPLACE FUNCTION public.nilo_rl_scomments() RETURNS trigger LANGUAGE plpgsql AS $function$ begin if (select count(*) from public.story_comments where author = new.author and created_at > now() - interval '24 hours') >= 200 then raise exception 'rate limit: too many comments today'; end if; return new; end $function$;

 CREATE OR REPLACE FUNCTION public.nilo_rl_stories() RETURNS trigger LANGUAGE plpgsql AS $function$ begin if (select count(*) from public.stories where author = new.author and created_at > now() - interval '24 hours') >= 20 then raise exception 'rate limit: too many stories today'; end if; return new; end $function$;

 CREATE OR REPLACE FUNCTION public.nilo_set_cc(c text) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path TO 'public' AS $function$ update public.profiles set cc = case when c ~ '^[A-Z]{2}$' then c else null end where id = auth.uid(); $function$;

 CREATE OR REPLACE FUNCTION public.nilo_stats() RETURNS json LANGUAGE sql SECURITY DEFINER SET search_path TO 'public' AS $function$ select json_build_object('people', (select count(*) from public.profiles where age_ok and cc is not null), 'floating', (select count(*) from public.bottles where status = 'floating')); $function$;

 CREATE OR REPLACE FUNCTION public.open_letter(c text, ct text) RETURNS letters LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare l public.letters; begin if not exists (select 1 from public.profiles where id = auth.uid() and age_ok) then raise exception 'age confirmation required'; end if; select * into l from public.letters where cc = upper(c) and lower(city) = lower(ct) and opened_by is null and author <> auth.uid() and not exists (select 1 from public.blocks k where (k.blocker = auth.uid() and k.blocked = letters.author) or (k.blocker = letters.author and k.blocked = auth.uid())) order by random() limit 1 for update skip locked; if l.id is null then return null; end if; update public.letters set opened_by = auth.uid(), opened_at = now() where id = l.id returning * into l; return l; end $function$;

 CREATE OR REPLACE FUNCTION public.pp_is_public(n text) RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path TO 'public' AS $function$ select exists(select 1 from public.profile_photos where path = n and is_public) $function$;

 CREATE OR REPLACE FUNCTION public.pp_limit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ begin if (select count(*) from public.profile_photos where uid = new.uid) >= 6 then raise exception 'max 6 photos'; end if; return new; end $function$;

 CREATE OR REPLACE FUNCTION public.purge_rows() RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path TO 'public' AS $function$ delete from public.stories where created_at < now() - interval '25 hours' $function$;

 CREATE OR REPLACE FUNCTION public.redeem_invite(c text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare t uuid; begin if not exists (select 1 from public.profiles where id = auth.uid() and invited_by is null) then return false; end if; select id into t from public.profiles where invite_code = lower(trim(c)) and id <> auth.uid(); if t is null then return false; end if; update public.profiles set invited_by = t where id = auth.uid(); return true; end $function$;

 CREATE OR REPLACE FUNCTION public.remove_friend(p_uid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ begin if auth.uid() is null then return; end if; delete from public.friendships where (requester = auth.uid() and target = p_uid) or (target = auth.uid() and requester = p_uid); end $function$;

 CREATE OR REPLACE FUNCTION public.report_chain_line(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ begin if auth.uid() is null then return; end if; if not exists (select 1 from public.chain_lines l where l.id = p_id and l.author <> auth.uid() and (public.nilo_in_chain(l.chain) or exists (select 1 from public.chains c where c.id = l.chain and c.holder = auth.uid()))) then return; end if; insert into public.chain_reports(line, reporter) values (p_id, auth.uid()) on conflict do nothing; if found then update public.chain_lines set reports = reports + 1 where id = p_id; end if; end $function$;

 CREATE OR REPLACE FUNCTION public.report_circle_post(pid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ begin insert into public.circle_reports (post, reporter) values (pid, auth.uid()) on conflict do nothing; update public.circle_posts set reports = (select count(*) from public.circle_reports where post = pid) where id = pid; end $function$;

 CREATE OR REPLACE FUNCTION public.report_daily_answer(pid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ begin insert into public.daily_reports (answer, reporter) values (pid, auth.uid()) on conflict do nothing; update public.daily_answers set reports = (select count(*) from public.daily_reports where answer = pid) where id = pid; end $function$;

 CREATE OR REPLACE FUNCTION public.report_dm(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ begin if auth.uid() is null then return; end if; if not exists (select 1 from public.dms where id = p_id and recipient = auth.uid()) then return; end if; insert into public.dm_reports(dm, reporter) values (p_id, auth.uid()) on conflict do nothing; if found then update public.dms set reports = reports + 1 where id = p_id; end if; end $function$;

 CREATE OR REPLACE FUNCTION public.report_group_msg(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ begin if auth.uid() is null then return; end if; if not exists (select 1 from public.chat_msgs m where m.id = p_id and public.nilo_in_group(m.grp) and m.sender <> auth.uid()) then return; end if; insert into public.chat_msg_reports(msg, reporter) values (p_id, auth.uid()) on conflict do nothing; if found then update public.chat_msgs set reports = reports + 1 where id = p_id; end if; end $function$;

 CREATE OR REPLACE FUNCTION public.report_place_user(p_user uuid, p_place text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ begin if auth.uid() is null or p_user is null or p_user = auth.uid() then return; end if; if exists(select 1 from public.place_reports where reporter=auth.uid() and reported=p_user and created_at > now() - interval '1 hour') then return; end if; insert into public.place_reports(reporter,reported,place) values (auth.uid(), p_user, left(coalesce(p_place,''),40)); end $function$;

 CREATE OR REPLACE FUNCTION public.report_profile(p_uid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ begin if auth.uid() is null or p_uid = auth.uid() then return; end if; insert into public.profile_reports(reporter, target) values (auth.uid(), p_uid) on conflict do nothing; end $function$;

 CREATE OR REPLACE FUNCTION public.report_story(sid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ begin insert into public.story_reports(story_id, reporter) values (sid, auth.uid()) on conflict do nothing; update public.stories set reports = (select count(*) from public.story_reports where story_id = sid) where id = sid; end $function$;

 CREATE OR REPLACE FUNCTION public.report_tip(pid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ begin insert into public.tip_reports (tip, reporter) values (pid, auth.uid()) on conflict do nothing; update public.tips set reports = (select count(*) from public.tip_reports where tip = pid) where id = pid; end $function$;

 CREATE OR REPLACE FUNCTION public.request_friend(p_code text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare r uuid; begin if auth.uid() is null then return 'auth'; end if; if not exists (select 1 from public.profiles where id = auth.uid() and age_ok) then return 'age'; end if; select id into r from public.profiles where invite_code = lower(trim(p_code)) and age_ok limit 1; if r is null then return 'nocode'; end if; if r = auth.uid() then return 'self'; end if; if exists (select 1 from public.blocks k where (k.blocker = r and k.blocked = auth.uid()) or (k.blocker = auth.uid() and k.blocked = r)) then return 'nocode'; end if; if exists (select 1 from public.friendships where requester = r and target = auth.uid()) then update public.friendships set status = 'accepted' where requester = r and target = auth.uid(); return 'accepted'; end if; insert into public.friendships(requester, target) values (auth.uid(), r) on conflict do nothing; return 'sent'; end $function$;

 CREATE OR REPLACE FUNCTION public.request_friend_uid(p_uid uuid) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare r uuid := p_uid; begin if auth.uid() is null then return 'auth'; end if; if not exists (select 1 from public.profiles where id = auth.uid() and age_ok) then return 'age'; end if; if not exists (select 1 from public.profiles where id = r and age_ok) then return 'nocode'; end if; if r = auth.uid() then return 'self'; end if; if exists (select 1 from public.blocks k where (k.blocker = r and k.blocked = auth.uid()) or (k.blocker = auth.uid() and k.blocked = r)) then return 'nocode'; end if; if exists (select 1 from public.friendships where requester = auth.uid() and target = r) then return 'sent'; end if; if exists (select 1 from public.friendships where requester = r and target = auth.uid()) then update public.friendships set status = 'accepted' where requester = r and target = auth.uid(); return 'accepted'; end if; insert into public.friendships(requester, target) values (auth.uid(), r) on conflict do nothing; return 'sent'; end $function$;

 CREATE OR REPLACE FUNCTION public.respond_friend(p_uid uuid, p_accept boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ begin if auth.uid() is null then return; end if; if p_accept then update public.friendships set status = 'accepted' where requester = p_uid and target = auth.uid(); else delete from public.friendships where requester = p_uid and target = auth.uid(); end if; end $function$;

 CREATE OR REPLACE FUNCTION public.riddle_answer(p_text text) RETURNS json LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare w public.wallet; today date := (now() at time zone 'utc')::date; n int; r public.riddles; tries int; ok boolean; a text; g int; begin if auth.uid() is null then raise exception 'auth'; end if; insert into public.wallet(uid) values (auth.uid()) on conflict do nothing; select * into w from public.wallet where uid = auth.uid() for update; if w.riddle_day = today and w.riddle_done then raise exception 'done'; end if; tries := case when w.riddle_day = today then w.riddle_tries else 0 end; if tries >= 5 then raise exception 'no_tries'; end if; select count(*) into n from public.riddles; select * into r from public.riddles where idx = (today - date '2026-01-01') % n; ok := false; foreach a in array r.answers loop if public.nilo_norm(a) = public.nilo_norm(left(p_text, 60)) then ok := true; end if; end loop; g := w.gems; if ok then g := g + 10; end if; update public.wallet set riddle_day = today, riddle_tries = tries + 1, riddle_done = ok, gems = g, xp = xp + (case when ok then 3 else 0 end) where uid = auth.uid(); return json_build_object('correct', ok, 'gems', g, 'tries_left', greatest(0, 4 - tries)); end $function$;

 CREATE OR REPLACE FUNCTION public.riddle_state() RETURNS json LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare w public.wallet; today date := (now() at time zone 'utc')::date; n int; r public.riddles; solved boolean; tries int; begin if auth.uid() is null then raise exception 'auth'; end if; insert into public.wallet(uid) values (auth.uid()) on conflict do nothing; select * into w from public.wallet where uid = auth.uid(); select count(*) into n from public.riddles; select * into r from public.riddles where idx = (today - date '2026-01-01') % n; solved := (w.riddle_day = today and w.riddle_done); tries := case when w.riddle_day = today then w.riddle_tries else 0 end; return json_build_object('q', r.q, 'q_ar', r.q_ar, 'solved', solved, 'tries_left', greatest(0, 5 - tries)); end $function$;

 CREATE OR REPLACE FUNCTION public.rls_auto_enable() RETURNS event_trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog' AS $function$ DECLARE cmd record; tbl name; BEGIN FOR cmd IN SELECT * FROM pg_event_trigger_ddl_commands() WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO') AND object_type IN ('table','partitioned table') LOOP IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN BEGIN SELECT c.relname INTO tbl FROM pg_catalog.pg_class c WHERE c.oid = cmd.objid; EXECUTE format('alter table if exists %I.%I enable row level security', cmd.schema_name, tbl); RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity; EXCEPTION WHEN OTHERS THEN RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity; END; ELSE RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name; END IF; END LOOP; END; $function$;

 CREATE OR REPLACE FUNCTION public.send_direct(p_code text, p_kind text, p_place text, p_body text, p_lang text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare r uuid; begin if auth.uid() is null then return false; end if; if not exists (select 1 from public.profiles where id = auth.uid() and age_ok) then return false; end if; select id into r from public.profiles where invite_code = lower(trim(p_code)) and age_ok limit 1; if r is null or r = auth.uid() then return false; end if; if exists (select 1 from public.blocks k where (k.blocker = r and k.blocked = auth.uid()) or (k.blocker = auth.uid() and k.blocked = r)) then return false; end if; insert into public.bottles(author, kind, place, body, lang, status, catcher) values (auth.uid(), case when p_kind in ('place','phrase','free') then p_kind else 'free' end, p_place, p_body, coalesce(p_lang,'en'), 'caught', r); return true; end $function$;

 CREATE OR REPLACE FUNCTION public.send_dm(p_uid uuid, p_body text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare t text := left(trim(coalesce(p_body,'')), 500); begin if auth.uid() is null or t = '' then return false; end if; if not exists (select 1 from public.profiles where id = auth.uid() and age_ok) then return false; end if; if not exists (select 1 from public.friendships f where f.status = 'accepted' and ((f.requester = auth.uid() and f.target = p_uid) or (f.target = auth.uid() and f.requester = p_uid))) then return false; end if; if exists (select 1 from public.blocks k where (k.blocker = p_uid and k.blocked = auth.uid()) or (k.blocker = auth.uid() and k.blocked = p_uid)) then return false; end if; if t ~* '(https?://|www\.|t\.me|wa\.me|\.com|\.net|\.org)' or t ~ '[0-9٠-٩]{6,}' then raise exception 'bad_text'; end if; if (select count(*) from public.dms where sender = auth.uid() and created_at > now() - interval '24 hours') >= 300 then raise exception 'rate limit'; end if; insert into public.dms(sender, recipient, body) values (auth.uid(), p_uid, t); return true; end $function$;

 CREATE OR REPLACE FUNCTION public.send_group_msg(p_grp uuid, p_body text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare t text := left(trim(coalesce(p_body,'')), 500); n text; begin if auth.uid() is null or t = '' then return false; end if; if not exists (select 1 from public.chat_members where grp = p_grp and uid = auth.uid()) then return false; end if; if not exists (select 1 from public.profiles where id = auth.uid() and age_ok) then return false; end if; if t ~* '(https?://|www\.|t\.me|wa\.me|\.com|\.net|\.org)' or t ~ '[0-9٠-٩]{6,}' then raise exception 'bad_text'; end if; if (select count(*) from public.chat_msgs where sender = auth.uid() and created_at > now() - interval '24 hours') >= 300 then raise exception 'rate limit'; end if; select nick into n from public.profiles where id = auth.uid(); insert into public.chat_msgs(grp, sender, nick, body) values (p_grp, auth.uid(), n, t); return true; end $function$;

 CREATE OR REPLACE FUNCTION public.set_cosmetic(p_kind text, p_key text) RETURNS json LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare w public.wallet; lv int; need int; begin if auth.uid() is null then raise exception 'auth'; end if; insert into public.wallet(uid) values (auth.uid()) on conflict do nothing; select * into w from public.wallet where uid = auth.uid() for update; lv := case when w.xp >= 700 then 3 when w.xp >= 300 then 2 when w.xp >= 100 then 1 else 0 end; if p_kind = 'frame' then need := case p_key when 'none' then 0 when 'gold' then 1 when 'jade' then 2 when 'aurora' then 3 else null end; if need is null then raise exception 'bad_key'; end if; if lv < need then raise exception 'locked'; end if; update public.wallet set frame = p_key where uid = auth.uid(); elsif p_kind = 'skin' then need := case p_key when 'classic' then 0 when 'nile' then 1 when 'dusk' then 2 when 'legend' then 3 else null end; if need is null then raise exception 'bad_key'; end if; if lv < need then raise exception 'locked'; end if; update public.wallet set skin = p_key where uid = auth.uid(); else raise exception 'bad_kind'; end if; return json_build_object('ok', true); end $function$;

 CREATE OR REPLACE FUNCTION public.set_gender(p_g text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ begin if auth.uid() is null then raise exception 'auth'; end if; if p_g not in ('m','f') then raise exception 'bad'; end if; update public.profiles set gender = p_g where id = auth.uid(); end $function$;

 CREATE OR REPLACE FUNCTION public.set_profile(p_bio text, p_avatar text, p_avatar_path text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ begin if auth.uid() is null then raise exception 'auth'; end if; if p_bio ~* '(https?://|www\.|@|t\.me|wa\.me|\.com|\.net|\.org)' or p_bio ~ '[0-9٠-٩]{6,}' then raise exception 'bad_bio'; end if; update public.profiles set bio = left(coalesce(p_bio,''),160), avatar = left(coalesce(p_avatar,''),12), avatar_path = case when p_avatar_path like auth.uid()::text || '/%' then p_avatar_path else '' end where id = auth.uid(); end $function$;

 CREATE OR REPLACE FUNCTION public.shop_buy(p_item text) RETURNS json LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare w public.wallet; price int; begin if auth.uid() is null then raise exception 'auth'; end if; price := case p_item when 'eye' then 30 else null end; if price is null then raise exception 'bad_item'; end if; insert into public.wallet(uid) values (auth.uid()) on conflict do nothing; select * into w from public.wallet where uid = auth.uid() for update; if w.gems < price then raise exception 'gems'; end if; update public.wallet set gems = gems - price, items = jsonb_set(items, array[p_item], to_jsonb(coalesce((items ->> p_item)::int, 0) + 1)) where uid = auth.uid() returning * into w; return json_build_object('gems', w.gems, 'items', w.items); end $function$;

 CREATE OR REPLACE FUNCTION public.start_chain(p_body text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare t text := left(trim(coalesce(p_body,'')), 160); c uuid; v_cc text; begin if auth.uid() is null then return null; end if; if not exists (select 1 from public.profiles where id = auth.uid() and age_ok) then return null; end if; if char_length(t) < 3 or t ~* '(https?://|www\.|@|t\.me|wa\.me|\.com|\.net|\.org)' or t ~ '[0-9٠-٩]{6,}' then raise exception 'bad_text'; end if; if (select count(*) from public.chains where starter = auth.uid() and created_at > now() - interval '24 hours') >= 3 then raise exception 'rate limit'; end if; select p.cc into v_cc from public.profiles p where p.id = auth.uid(); insert into public.chains(starter) values (auth.uid()) returning id into c; insert into public.chain_lines(chain, author, country, body, pos) values (c, auth.uid(), v_cc, t, 1); return c; end $function$;

 CREATE OR REPLACE FUNCTION public.storage_ok() RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path TO 'public', 'storage' AS $function$ select coalesce(sum((metadata->>'size')::bigint), 0) < 800 * 1024 * 1024 from storage.objects where bucket_id = 'stories' $function$;

 CREATE OR REPLACE FUNCTION public.stories_limit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ begin if (select count(*) from public.stories where author = new.author and created_at > now() - interval '24 hours') >= 6 then raise exception 'daily story limit'; end if; if new.media_path is not null and (select count(*) from public.stories where author = new.author and media_path is not null and created_at > now() - interval '24 hours') >= 3 then raise exception 'daily media limit'; end if; return new; end $function$;

 CREATE OR REPLACE FUNCTION public.tip_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ begin new.reports := 0; if new.body ~* '(https?://|www\.|@|t\.me|wa\.me|\.com|\.net|\.org)' or new.body ~ '[0-9٠-٩]{6,}' then raise exception 'bad_text'; end if; if (select count(*) from public.tips where author = new.author and created_at > now() - interval '24 hours') >= 5 then raise exception 'rate limit: too many tips today'; end if; return new; end $function$;




